async function hunt() {
    const targets = ['Rat', 'Man', 'Woman', 'Butterfly', 'Imp', 'Chicken', 'Cow', 'Goblin'];
    for (const targetName of targets) {
        let killed = false;
        while (!killed) {
            const res = await bot.attack(targetName);
            if (res.success) {
                // Wait for combat to end or target to be killed
                while (sdk.getState()?.player?.combat.inCombat) {
                    await sdk.waitForStateUpdate();
                }
                killed = true;
            } else {
                // If not found, try to move or break
                break;
            }
        }
    }
}
await hunt();

async function healAndHunt() {
    await bot.eatFood();
    const targets = ['Butterfly', 'Imp', 'Chicken', 'Cow', 'Goblin'];
    for (const targetName of targets) {
        const res = await bot.attack(targetName);
        if (res.success) {
            while (sdk.getState()?.player?.combat.inCombat) {
                if (sdk.getState()?.player?.hp < 5) {
                    await bot.eatFood();
                }
                await sdk.waitForStateUpdate();
            }
        }
    }
}
await healAndHunt();

